
window.globalScriptReady = new Promise(resolve => {
    document.addEventListener('DOMContentLoaded', async () => {
        resolve();

        document.querySelectorAll('.quiet-loop').forEach(function(audio) {
          audio.volume = 0.2;
          audio.loop = true;

          const isGithub = window.location.hostname.includes('github.io');
          const base = isGithub ? '/grammar_of_english' : '';
          const source = audio.querySelector('source');
          if (source) {
            const originalSrc = source.getAttribute('src');
            source.src = base + originalSrc;
            audio.load();
          }

        });

    });
});

document.addEventListener('keydown', function(e) {
    // не даем mdBook обработать спец. keydown которые будут мешать вводить данные
    if ((e.key === 's' || e.key === 'S' || e.key === 'ы' || e.key === '/') && !e.ctrlKey && !e.metaKey) {
        e.stopImmediatePropagation();
    }
    if ((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && !e.ctrlKey && !e.metaKey) {
        e.stopImmediatePropagation();
        if (e.key === 'ArrowLeft') document.getElementById('listen-manual-repeat')?.click();
        if (e.key === 'ArrowRight') document.getElementById('listen-manual-next')?.click();
    }
    if (e.shiftKey && e.key === '?') {
        e.stopImmediatePropagation(); 
    }
}, true);


