function get_words_b1(){

    let result = [];
 
    for (let i = 0; i < b1_words_preposition.length; i++) {  
        if (!result.includes(b1_words_preposition[i][0])) {
            result.push(b1_words_preposition[i][0]);
        }
    }
    for (let i = 0; i < b1_words_adjective.length; i++) {  
        if (!result.includes(b1_words_adjective[i][0])) {
            result.push(b1_words_adjective[i][0]);
        }
        if (b1_words_adjective[i][1]!="" && !result.includes(b1_words_adjective[i][1])) {
            result.push(b1_words_adjective[i][1]);
        }
        if (b1_words_adjective[i][2]!="" && !result.includes(b1_words_adjective[i][2])) {
            result.push(b1_words_adjective[i][2]);
        }
    }
    for (let i = 0; i < b1_words_adverbs.length; i++) {  
        if (!result.includes(b1_words_adverbs[i][0])) {
            result.push(b1_words_adverbs[i][0]);
        }
    }
    for (let i = 0; i < b1_words_verbs.length; i++) {  
        if (!result.includes(b1_words_verbs[i][0])) {
            result.push(b1_words_verbs[i][0]);
        }
        if (!result.includes(b1_words_verbs[i][1])) {
            result.push(b1_words_verbs[i][1]);
        }
       if (!result.includes(b1_words_verbs[i][2])) {
            result.push(b1_words_verbs[i][2]);
        }
        if (!result.includes(b1_words_verbs[i][3])) {
            result.push(b1_words_verbs[i][3]);
        }
        if (!result.includes(b1_words_verbs[i][4])) {
            result.push(b1_words_verbs[i][4]);
        }
    }
    for (let i = 0; i < b1_words_nouns.length; i++) {  
        if (!result.includes(b1_words_nouns[i][0])) {
            result.push(b1_words_nouns[i][0]);
        }
        if (!result.includes(b1_words_nouns[i][1])) {
            result.push(b1_words_nouns[i][1]);
        }
        if (!result.includes(b1_words_nouns[i][2])) {
            result.push(b1_words_nouns[i][2]);
        }        
    }
    return result;
}

